  /* V2.95: chuỗi việc làm tiếp. Mỗi việc nối tiếp ghi tiepTu (id việc trước). Từ đó tính: việc này là bước mấy trên tổng bao nhiêu bước của chuỗi,
     và việc đầu chuỗi biết có bao nhiêu việc làm tiếp từ nó. Việc không thuộc chuỗi nào thì trả null (dòng bình thường, không chip). */
  function tiepInfo(r){
    if(!r)return null;var all=allResults(),by={};all.forEach(function(x){by[x.id]=x;});
    function lenLen(x){var n=0;while(x&&x.tiepTu&&by[x.tiepTu]&&n<40){x=by[x.tiepTu];n++;}return {goc:x,sau:n};}
    var me=lenLen(r),goc=me.goc||r,tong=1,kids=0;
    all.forEach(function(x){if(x.id!==goc.id&&x.tiepTu){var t=lenLen(x);if(t.goc&&t.goc.id===goc.id){tong=Math.max(tong,t.sau+1);kids++;}}});
    if(!r.tiepTu&&!kids)return null;
    var buoc=r.tiepTu?(by[r.tiepTu]?me.sau+1:Math.max(Number(r.buoc)||2,2)):1;
    return {buoc:buoc,tong:Math.max(tong,buoc),kids:kids};}
  function tiepChip(r){
    var t=tiepInfo(r);if(!t)return '';
    if(!r.tiepTu)return '<span class="rr-tiep rr-goc" title="Việc mở đầu một chuỗi: các việc sau làm nối tiếp từ kết quả của nó"><span class="rr-tiep-b">Bước 1/'+t.tong+'</span> việc mở đầu, có '+t.kids+' việc làm tiếp</span>';
    var p=findResult(r.tiepTu);
    return '<button type="button" class="rr-tiep" data-tiep-id="'+esc(r.tiepTu)+'"'+(p?' data-result-open="'+esc(r.tiepTu)+'"':'')+' title="Mở việc trước"><span class="rr-tiep-b">Bước '+t.buoc+'/'+t.tong+'</span> làm tiếp từ <b class="rr-tiep-ten">'+esc(String(r.tiepTen||'').slice(0,60))+'</b>'+(p&&p.time?' <span class="rr-tiep-gio">('+esc(p.time)+')</span>':'')+'</button>';}
