    var BG_TU={video:/mp4|mov|video|dựng|clip|reel|tiktok|a-roll|b-roll|phụ đề/i,am:/mp3|âm thanh|nhạc|giọng|voice|podcast|audio/i,bang:/xlsx|excel|csv|trang tính|bảng|sheet/i,slide:/pptx|ppt|slide|trình chiếu|thuyết trình/i,
