/* V2.96: việc làm tiếp nằm TRONG việc mở đầu (kết quả 1 -> 2 -> 3 hiện như mục con của kết quả 1).
   chainTree: nhận danh sách đã lọc, gom mỗi việc nối tiếp vào tổ tiên gần nhất còn trong danh sách. Cả chuỗi xếp theo lần làm MỚI NHẤT
   của nó (việc mới nhất vẫn ở trên cùng), các bước con xếp theo thời gian tăng dần. Chuỗi bị lọc mất việc mở đầu thì các bước còn lại
   hiện như dòng thường (chip "Bước n/m, làm tiếp từ ..." vẫn cho biết nối từ đâu). */
function chainKey(r){return (r.date||'')+'|'+String(r.created||r.time||'');}
function chainTree(rs,all){
  var by={},inRs={};all.forEach(function(x){by[x.id]=x;});rs.forEach(function(x){inRs[x.id]=x;});
  function anc(x){var n=0,p=x.tiepTu;while(p&&n<40){if(inRs[p]&&p!==x.id)return inRs[p];var q=by[p];p=q&&q.tiepTu;n++;}return null;}
  var kids={},tops=[];
  rs.forEach(function(r){var a=r.tiepTu?anc(r):null;if(a)(kids[a.id]=kids[a.id]||[]).push(r);else tops.push(r);});
  var placed={};
  function walk(r,d,out){(kids[r.id]||[]).slice().sort(function(a,b){var x=chainKey(a),y=chainKey(b);return x<y?-1:x>y?1:0;}).forEach(function(c){
    if(placed[c.id])return;placed[c.id]=1;out.push({r:c,d:d});walk(c,d+1,out);});}
  function build(r){placed[r.id]=1;var out=[];walk(r,1,out);var last=r;out.forEach(function(o){if(chainKey(o.r)>chainKey(last))last=o.r;});
    return {r:r,kids:out,key:chainKey(last),day:last.date||r.date||''};}
  var res=tops.map(build);
  rs.forEach(function(r){if(!placed[r.id])res.push(build(r));});   /* vòng nối tiếp lạ: vẫn hiện, không để mất việc */
  return res;}
function tiepChipN(r){var t=tiepInfo(r);return t?'<span class="rr-tiep rr-tiep-n"><span class="rr-tiep-b">Bước '+t.buoc+'/'+t.tong+'</span></span>':'';}
